// CouponDuration says which of a subscription's invoices a coupon discounts.
type CouponDuration string

// Coupon durations.
const (
	// DurationOnce discounts only the first invoice created after the coupon was applied.
	DurationOnce CouponDuration = "once"
	// DurationRepeating discounts the invoices whose period starts less than DurationInMonths months after the redemption.
	DurationRepeating CouponDuration = "repeating"
	// DurationForever discounts every invoice created after the coupon was applied.
	DurationForever CouponDuration = "forever"
)

// Coupon is a discount an organization offers under a code. Exactly one of PercentOff and AmountOff is set.
type Coupon struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
	// Code is what the customer types. It is unique in the organization, ignoring case.
	Code       string `json:"code"`
	PercentOff int    `json:"percent_off,omitempty"`
	// AmountOff is in the currency's minor unit; Currency is set with it.
	AmountOff        int64          `json:"amount_off,omitempty"`
	Currency         money.Currency `json:"currency,omitempty"`
	Duration         CouponDuration `json:"duration"`
	DurationInMonths int            `json:"duration_in_months,omitempty"`
	// MaxRedemptions is how many subscriptions may hold the coupon; 0 means no limit.
	MaxRedemptions int `json:"max_redemptions,omitempty"`
	// RedeemBy is the last time the coupon can be applied; nil means it never expires.
	RedeemBy  *time.Time `json:"redeem_by,omitempty"`
	CreatedAt time.Time  `json:"created_at"`
}

// Subscription is a customer's subscription to a plan.
type Subscription struct {
	ID              string    `json:"id"`
	OrgID           string    `json:"org_id"`
	CustomerID      string    `json:"customer_id"`
	PlanID          string    `json:"plan_id"`
	Quantity        int       `json:"quantity"`
	Status          SubStatus `json:"status"`
	DiscountPercent int       `json:"discount_percent"`
	// Coupon is the code of the coupon applied to the subscription, "" when none.
	Coupon           string     `json:"coupon"`
	CouponRedeemedAt *time.Time `json:"coupon_redeemed_at,omitempty"`
	// StartedAt is when the subscription began; its billing periods are counted from it.
	StartedAt          time.Time  `json:"started_at"`
	CurrentPeriodStart time.Time  `json:"current_period_start"`
	CurrentPeriodEnd   time.Time  `json:"current_period_end"`
	TrialEnd           *time.Time `json:"trial_end,omitempty"`
	CancelAtPeriodEnd  bool       `json:"cancel_at_period_end"`
	CanceledAt         *time.Time `json:"canceled_at,omitempty"`
	CreatedAt          time.Time  `json:"created_at"`
}

